index 0000000..6fb8dec
--- /dev/null
+++ b/src/main/java/hotel/notifications/GovernanceNotifier.java
@@ -0,0 +1,45 @@
+package hotel.notifications;
+
+import static hotel.documents.TextFormat.date;
+
+import hotel.messages.EmailSender;
+import hotel.reservations.Reservation;
+import hotel.reservations.ReservationListener;
+
+/** Tells housekeeping which rooms to prepare, and which ones were freed. */
+public final class GovernanceNotifier implements ReservationListener {
+
+    public static final String ADDRESS = "governanca@pousadamarealta.com.br";
+
+    private final EmailSender emailSender;
+
+    public GovernanceNotifier(EmailSender emailSender) {
+        this.emailSender = emailSender;
+    }
+
+    @Override
+    public void onConfirmed(Confirmed event) {
+        Reservation reservation = event.reservation();
+        emailSender.send(
+                ADDRESS,
+                "Reserva confirmada - quarto " + event.room().number(),
+                "Quarto " + event.room().number() + " reservado.\n"
+                        + "Entrada: " + date(reservation.checkIn()) + "\n"
+                        + "Saída: " + date(reservation.checkOut()) + "\n"
+                        + "Hóspedes: " + reservation.guests() + "\n");
+    }
+
+    @Override
+    public void onCancelled(Cancelled event) {
+        if (!event.wasConfirmed()) {
+            return;
+        }
+        Reservation reservation = event.reservation();
+        emailSender.send(
+                ADDRESS,
+                "Reserva cancelada - quarto " + event.room().number(),
+                "A reserva do quarto " + event.room().number() + " foi cancelada.\n"
+                        + "Datas liberadas: de " + date(reservation.checkIn())
+                        + " a " + date(reservation.checkOut()) + "\n");
+    }
+}
diff --git a/src/main/java/hotel/notifications/StaffNotifications.java b/src/main/java/hotel/notifications/StaffNotifications.java
new file mode 100644
index 0000000..c62ccb3
--- /dev/null
+++ b/src/main/java/hotel/notifications/StaffNotifications.java
@@ -0,0 +1,16 @@
+package hotel.notifications;
+
+import hotel.messages.EmailSender;
+import hotel.reservations.ReservationListener;
+import java.util.List;
+
+/** The staff who are told about reservations. To add or remove someone, change this list. */
+public final class StaffNotifications {
+
+    private StaffNotifications() {
+    }
+
+    public static List<ReservationListener> all(EmailSender emailSender) {
+        return List.of(new GovernanceNotifier(emailSender), new FinanceNotifier(emailSender));
+    }
+}
diff --git a/src/main/java/hotel/reservations/ReservationListener.java b/src/main/java/hotel/reservations/ReservationListener.java
new file mode 100644
index 0000000..1ee67e2
--- /dev/null
+++ b/src/main/java/hotel/reservations/ReservationListener.java
@@ -0,0 +1,26 @@
+package hotel.reservations;
+
+import hotel.rooms.Room;
+import java.math.BigDecimal;
+
+/**
+ * Someone who wants to know when something happens to a reservation. Register one in the
+ * {@link ReservationService} to be told; override only the events you care about.
+ */
+public interface ReservationListener {
+
+    /** The guest paid and the reservation is now confirmed. */
+    default void onConfirmed(Confirmed event) {
+    }
+
+    /** A reservation was cancelled. */
+    default void onCancelled(Cancelled event) {
+    }
+
+    record Confirmed(Reservation reservation, Room room) {
+    }
+
+    /** {@code wasConfirmed} tells whether it had been paid and confirmed before the cancellation. */
+    record Cancelled(Reservation reservation, Room room, boolean wasConfirmed, BigDecimal refund) {
+    }
+}
