                 "Reserva confirmada - " + HOTEL_NAME,
                 confirmationEmailBody(reservation, receipt));
+        notifyListeners(listener -> listener.onConfirmed(
+                new ReservationListener.Confirmed(reservation, roomOf(reservation))));
         return reservation;
     }

@@ -83,8 +100,11 @@ public final class ReservationService {
             case STANDARD -> reservation.amountPaid();
             case NON_REFUNDABLE -> PriceCalculator.cents(BigDecimal.ZERO);
         };
+        boolean wasConfirmed = reservation.status() == ReservationStatus.CONFIRMED;
         reservation.cancel(refund);
         store.update(reservation);
+        notifyListeners(listener -> listener.onCancelled(
+                new ReservationListener.Cancelled(reservation, roomOf(reservation), wasConfirmed, refund)));
         return reservation;
     }

@@ -118,6 +138,25 @@ public final class ReservationService {
         return new ReservationReceipt(reservation, roomOf(reservation));
     }

+    /** Tells every listener, even if one of them fails; the first failure is rethrown at the end. */
+    private void notifyListeners(Consumer<ReservationListener> event) {
+        RuntimeException failure = null;
+        for (ReservationListener listener : listeners) {
+            try {
+                event.accept(listener);
+            } catch (RuntimeException e) {
+                if (failure == null) {
+                    failure = e;
+                } else {
+                    failure.addSuppressed(e);
+                }
+            }
+        }
+        if (failure != null) {
+            throw failure;
+        }
+    }
+
     private Room roomOf(Reservation reservation) {
         return rooms.find(reservation.roomNumber()).orElseThrow();
     }
