    42	    public synchronized Reservation create(NewReservation request) {
    43	        if (!request.checkOut().isAfter(request.checkIn())) {
    44	            throw new HotelException(ErrorCode.INVALID_REQUEST, "check-out must be after check-in");
    45	        }
    46	        if (request.guests() < 1) {
    47	            throw new HotelException(ErrorCode.INVALID_REQUEST, "a reservation needs at least one guest");
    48	        }
    49	        Room room = rooms.find(request.roomNumber())
    50	                .orElseThrow(() -> new HotelException(
    51	                        ErrorCode.ROOM_NOT_FOUND, "room " + request.roomNumber() + " does not exist"));
    52	        if (request.guests() > room.capacity()) {
    53	            throw new HotelException(
    54	                    ErrorCode.CAPACITY_EXCEEDED,
    55	                    "room " + room.number() + " takes at most " + room.capacity() + " guests");
    56	        }
    57	        if (store.isRoomTaken(room.number(), request.checkIn(), request.checkOut())) {
    58	            throw new HotelException(
    59	                    ErrorCode.ROOM_UNAVAILABLE, "room " + room.number() + " is taken on some of those nights");
    60	        }
    61	        Price price = priceCalculator.calculate(room, request.checkIn(), request.checkOut(), request.ratePlan());
    62	        return store.add(request, price);
